insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('aa01', null, 9, '{"rows":["...X.O...","...XO....","...XO....","...XO....","...XO....","...XXO...","...X.XO..","....XO...","....XO..."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue E3 : il prend F3, et c’est un ko. Tu ne peux pas reprendre tout de suite, et Blanc relie ensuite en F3."}', array['E3'], 'Ferme le ko', 'Ta pierre F3 est en atari (une seule liberté). Il reste aussi un point neutre, E9. Joue le bon coup.', 'Bravo ! E3 relie F3 : Blanc ne peut plus la prendre. Si tu joues E9 d’abord, Blanc prend F3 en E3. C’est un ko : une prise d’une pierre qu’on ne peut pas reprendre tout de suite. Blanc relie ensuite en F3, et tu perds 1 point. E9, une dame, ne rapporte rien.', 850),
 ('aa02', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".XXXXXX..",".XTTTTX..",".O..TXX.."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue C1, et tu ne peux plus prendre ses pierres tout de suite. Si tu as joué A1, il n’a même pas besoin de répondre."}', array['C1'], 'Une pierre pour six', 'Capture les pierres marquées en deux coups au plus.', 'Bravo ! C1 se met en atari exprès. Si Blanc la prend en D1, ses pierres n’ont plus qu’une liberté, C1 : tu y rejoues et tu en prends 6. C’est une prise en retour. Sinon, tu prends en D1. D1 d’abord ne marchait pas : Blanc prenait en C1 et se reliait à B1.', 900),
 ('aa03', null, 9, '{"rows":["..XX.O...","..X.OO...","...XO....","...XO....","...XO....","...XO....","XXXXOOOOO","XXXXOOOOO","XX.....OO"],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue D1 (ou E1 si tu as joué C1 ou D1) : c’est lui qui avance au premier rang."}', array['E1'], 'Le hane avant les dames', 'Il reste des points ouverts en haut et en bas. Joue le coup qui rapporte le plus.', 'Bravo ! E1 se glisse sous la pierre blanche E2, au premier rang : c’est un hane. Blanc bloque en F1, tu relies en D1. Bloquer en D1 rapportait 1 point de moins. En haut, E9 et D8 sont des dames, des points neutres : ils ne rapportent rien.', 900),
 ('aa04', null, 9, '{"rows":[".....OS.O",".....OXO.",".....OXO.",".....OXXX",".....OOOO",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue J7, et ton groupe finit pris."}', array['J7'], 'Partager les libertés', 'Sauve ton groupe marqué par un seki (vie commune) : il ne peut plus faire deux yeux.', 'Bravo ! Après J7, ton groupe et les pierres blanches partagent deux libertés, H9 et J8. Celui qui en remplit une se met en atari et se fait prendre : personne n’y joue. C’est seki, et ton groupe vit avec. Si Blanc joue J7 le premier, il prend ton groupe.', 950),
 ('aa05', null, 9, '{"rows":["......OS.","......OX.","......OXX","......OX.","......OX.","......OO.","......O.O",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue J5 : ton espace rétrécit, et tu ne fais plus deux yeux."}', array['J5'], 'Agrandis ton espace', 'Noir joue et vit. Ta pierre J7 est déjà au premier rang.', 'Bravo ! J5 agrandit ton espace. J6, entre J7 et J5, devient un œil, et J8-J9 en fait un autre : tu as deux yeux. Si Blanc joue J5 le premier, ton espace est trop petit.', 950),
 ('aa06', null, 9, '{"rows":[".........",".........",".........",".........",".........","....OOOOO","....OXXXS","....OX...","....O...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue H1 (ou G1 si tu as joué H2, ou H2 si tu as joué G1) : tu ne fais plus deux yeux."}', array['H1'], 'Le point du coin', 'Noir joue et vit. Ton espace fait sept points, dans le coin.', 'Bravo ! H1 est le point clé. Si Blanc joue H2, tu réponds J2 ; s’il joue J2, tu réponds H2 : tu fais toujours deux yeux. En H2, Blanc répondait G1, et tu n’avais plus qu’un ko.', 950),
 ('aa07', null, 9, '{"rows":[".........",".........",".........",".........",".....XXXX",".....XTTT",".....XT..",".....XXOX",".....X.O."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue H3 : il relie ses pierres à H2 et H1, et tu ne peux plus les prendre tout de suite."}', array['H3'], 'Jette-toi dedans', 'Capture les pierres marquées en deux coups au plus.', 'Bravo ! H3 se jette entre les pierres blanches : elles n’ont plus qu’une liberté, J3. Si Blanc prend ta pierre en J3, il ne lui reste que H3 : tu y rejoues et tu prends 5 pierres. C’est une prise en retour. En J3 d’abord, Blanc reliait tout en H3.', 1000),
 ('aa08', null, 9, '{"rows":["....O....","X.OXO....","OSXXO....","OOOOO....",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue C9 : sa pierre C8 a de nouveau deux libertés au moins, et tu ne fais plus deux yeux."}', array['C9'], 'Atari pour un œil', 'Noir joue et vit. Blanc a joué C8, au milieu de ton espace.', 'Bravo ! C9 met la pierre C8 en atari (une seule liberté). Si Blanc la prolonge en B8, tu prends les deux pierres en B9 ; s’il joue B9, tu prends C8 en B8. Tu fais deux yeux.', 1000),
 ('aa09', null, 9, '{"rows":[".........",".........",".........","OOOO.....","XXXO.....","..XO.....","O.XO.....","O.XO.....","XXSO....."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B3, et ton groupe finit pris."}', array['B3'], 'Seki au bord', 'Sauve ton groupe marqué par un seki (vie commune) : il ne peut plus faire deux yeux.', 'Bravo ! Si Blanc ne répond pas, A4 met A2 et A3 en atari, et ton groupe vit. Blanc doit donc jouer A4 lui-même. Ton groupe et ses pierres partagent alors deux libertés, B2 et B4 : celui qui en remplit une se fait prendre. C’est seki.', 1050),
 ('aa10', null, 9, '{"rows":[".........",".........",".........",".........","XXXX.....",".OOX.....","..OX.....",".OTX.....",".OXX....."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue A3, et tu ne peux plus prendre son groupe."}', array['A3'], 'Au milieu du bord', 'Noir joue et tue.', 'Bravo ! A3 est le point vital : il touche B3, A2 et A4. Si Blanc joue A2, tu joues A4 ; s’il joue A4, tu joues A2. Il ne fait jamais deux yeux.', 1050),
 ('aa11', null, 9, '{"rows":[".........",".........",".........",".........",".........","XXXXX....","TOOOX....","...OX....","..O.X...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B2, et tu ne peux plus prendre son groupe."}', array['B2'], 'Après le hane blanc', 'Noir joue et tue. Blanc vient de jouer C1.', 'Bravo ! B2 est le point vital de l’espace blanc. Si Blanc joue A2, tu réponds B1 ; s’il joue B1, tu réponds A2. Il ne fait jamais deux yeux.', 1100),
 ('aa12', null, 9, '{"rows":[".........",".........",".........",".........",".........","OOOOO....","SXXXO....","O..XO....","....O...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B2, et ton groupe meurt, même si tu gagnes tous les ko."}', array['B2'], 'Un ko pour vivre', 'Noir joue : vivre sans ko est impossible ici. Obtiens au moins un ko (une prise qu’on ne peut pas reprendre tout de suite).', 'Bravo ! B2 met la pierre A2 en atari. Blanc ne peut plus te tuer sans gagner un ko : si c’est toi qui le gagnes, tu vis. Après tout autre coup, ton groupe mourait, ko ou pas.', 1100),
 ('aa13', null, 9, '{"rows":["....X....","....XO..O","....XOOOT","....XXXXX",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue H9, et tu ne peux plus prendre son groupe."}', array['H9'], 'Le point vital du coin', 'Noir joue et tue.', 'Bravo ! H9 touche J9, G9 et H8 : c’est le point vital. Si Blanc joue H8, tu réponds G9 ; s’il joue G9, tu réponds H8. Il ne fait jamais deux yeux.', 1100),
 ('aa14', null, 9, '{"rows":[".........",".........",".........",".........",".........","...OOOOOO","...OXXXXS","...OX.OO.","...OX.OO."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue J2 : le carré a alors plus de libertés que ton groupe, et il le prend."}', array['J2'], 'Le carré blanc', 'Sauve ton groupe marqué par un seki (vie commune) : il ne peut plus faire deux yeux.', 'Bravo ! J2 enlève une liberté au carré blanc. Ton groupe et le carré partagent alors toutes leurs libertés : J1, F1 et F2. Personne ne peut plus prendre l’autre : c’est seki. Si Blanc joue J2 le premier, il a plus de libertés que toi et prend ton groupe.', 1150),
 ('aa15', null, 9, '{"rows":["...OX....","...OX..O.","...OXXXXS","...OOOOOO",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue G8 : sa pierre H8 s’agrandit, et tu ne fais plus deux yeux."}', array['G8'], 'Enferme la pierre blanche', 'Noir joue et vit. Blanc vient de jouer H8, dans ton espace.', 'Bravo ! G8 enferme la pierre H8 : elle n’a plus que deux libertés, J8 et H9. Quoi que Blanc joue ensuite, tu fais deux yeux. Si Blanc joue G8 le premier, tu ne fais plus deux yeux.', 1150),
 ('aa16', null, 9, '{"rows":[".........",".........",".........",".........",".........","OOOOOOO..","OSXXXXO..","OXO..XO..","O.....O.."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue D2, et tu ne fais plus deux yeux."}', array['D2'], 'Deux paires miai', 'Noir joue et vit. Blanc a joué C2, dans ton espace.', 'Bravo ! Après D2, B1 et C1 sont miai : deux points qui se valent. Si Blanc prend l’un, tu prends l’autre. E1 et F1 aussi. Quoi que Blanc joue, tu fais deux yeux.', 1200),
 ('aa17', null, 9, '{"rows":[".....XT..",".....XOO.",".....XO..",".....XOO.",".....XXXX",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue J7, et son groupe vit, même si tu gagnes tous les ko."}', array['J7'], 'Un ko pour tuer', 'Noir joue : tuer sans ko est impossible ici. Obtiens au moins un ko (une prise qu’on ne peut pas reprendre tout de suite).', 'Bravo ! Après J7, Blanc ne peut plus vivre sans gagner un ko : si c’est toi qui le gagnes, son groupe meurt. Après tout autre coup, Blanc vivait, ko ou pas.', 1200),
 ('aa18', null, 9, '{"rows":["..X...X..","TOOOOX...","XXXXXXX..",".........",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B9 : ta pierre C9 est en atari, et tu ne peux plus prendre son groupe."}', array['B9'], 'Cinq pierres au bord', 'Noir joue et tue. Ta pierre C9 est déjà dans l’espace blanc.', 'Bravo ! B9 se relie à ta pierre C9. Si Blanc joue D9, tu réponds F9 ; s’il joue F9, tu réponds D9. Il ne fait jamais deux yeux.', 1200),
 ('aa19', null, 9, '{"rows":["XO....X..","XOO..OX..","XXTOOOX..",".XXXXXX..",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue D9, et tu ne peux plus prendre son groupe."}', array['D9'], 'Le point sous le bord', 'Noir joue et tue.', 'Bravo ! D9 est le point vital. Si Blanc joue D8, tu réponds E9 ; s’il joue E9, tu réponds D8. Il ne fait jamais deux yeux.', 1250),
 ('aa20', null, 9, '{"rows":[".........",".........",".........",".........",".....XXXX",".....XOOT",".....XOO.",".....XOO.",".....XO.."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue J2, et son groupe vit, même si tu gagnes tous les ko."}', array['J2'], 'Le ko du coin', 'Noir joue : tuer sans ko est impossible ici. Obtiens au moins un ko (une prise qu’on ne peut pas reprendre tout de suite).', 'Bravo ! J2 se place au milieu de l’espace blanc. Si Blanc joue J1, tu prends en H1 : c’est un ko. Si c’est toi qui le gagnes, son groupe meurt. Après tout autre coup, Blanc vivait, ko ou pas.', 1250)
